import csv, json, os, sys, math
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

# ---------- Load data ----------
def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

config = json.load(open(os.path.join(DATA, "config.json")))
vertiports = {r["vertiport_id"]: r for r in read_csv("vertiports.csv")}
aircraft = {r["aircraft_id"]: r for r in read_csv("aircraft.csv")}
routes = {}
for r in read_csv("routes.csv"):
    routes[(r["origin"], r["destination"])] = r
requests = {r["request_id"]: r for r in read_csv("requests.csv")}
scenarios = {r["scenario_id"]: r for r in read_csv("scenarios.csv")}
route_avail = {}
for r in read_csv("scenario_route_availability.csv"):
    route_avail[(r["scenario_id"], r["origin"], r["destination"])] = r
air_avail = {}
for r in read_csv("scenario_aircraft_availability.csv"):
    air_avail[(r["scenario_id"], r["aircraft_id"])] = r
grid = {}
for r in read_csv("grid_prices.csv"):
    grid[(r["vertiport_id"], int(r["slot"]))] = r
floors = {r["origin"]: int(r["minimum_accepted_passengers"]) for r in read_csv("origin_service_floors.csv")}
groups = {}
for r in read_csv("request_groups.csv"):
    gid = r["group_id"]
    if gid not in groups:
        groups[gid] = {"requests": [], "spread": int(r["max_departure_spread_slots"])}
    groups[gid]["requests"].append(r["request_id"])
svc_windows = []
for r in read_csv("aircraft_service_windows.csv"):
    svc_windows.append(r)
reserves = []
for r in read_csv("emergency_reserve_requirements.csv"):
    reserves.append(r)
corridor_ctrl = {}
for r in read_csv("corridor_slot_controls.csv"):
    corridor_ctrl[(r["scenario_id"], r["corridor_id"], int(r["start_slot"]), int(r["end_slot"]))] = int(r["max_flights_per_slot"])
time_slots = {int(r["slot"]): r for r in read_csv("time_slots.csv")}

H = config["planning_horizon_slots"]  # 32, slots 0..31
RESERVE_SOC = config["reserve_soc_kwh"]
CHARGE_EFF = config["charge_efficiency"]
HIGH_SOC_FRAC = config["high_soc_threshold_fraction"]
TAPER_FRAC = config["taper_charge_fraction"]
DELAY_PEN = config["delay_penalty_per_passenger_slot"]
REPOS_COST = config["reposition_cost_per_kwh"]
TAIL_ALPHA = config["tail_risk_alpha"]
TAIL_W = config["tail_risk_weight"]
SLOT_H = config["slot_minutes"] / 60.0

S_list = list(scenarios.keys())
A_list = list(aircraft.keys())
R_list = list(requests.keys())
V_list = list(vertiports.keys())

# Precompute scenario route params
def route_dur(s, o, d):
    r = route_avail.get((s, o, d))
    if not r or int(r["open"]) == 0:
        return None
    base = routes[(o, d)]["flight_slots"]
    mult = float(r["flight_slot_multiplier"])
    gd = int(scenarios[s]["global_delay_slots"])
    return max(1, int(math.ceil(base * mult)) + gd)

def route_energy(s, o, d):
    r = route_avail.get((s, o, d))
    if not r or int(r["open"]) == 0:
        return None
    base = float(routes[(o, d)]["energy_kwh"])
    return base * float(r["energy_multiplier"])

def route_open(s, o, d):
    r = route_avail.get((s, o, d))
    return r is not None and int(r["open"]) == 1

# ---------- Build model ----------
model = Model("evtol_recovery")
model.setParam("gaprel", 0.0005)
model.setParam("limits/time", 300.0)
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        model.setParam("limits/time", min(300.0, float(env_limit)))
    except ValueError:
        pass

# First-stage variables
x = {}
for r in R_list:
    x[r] = model.addVar(name=f"x_{r}", vtype="B", lb=0, ub=1, obj=0.0)

# Group all-or-nothing
for gid, g in groups.items():
    reqs = g["requests"]
    if len(reqs) > 1:
        for r2 in reqs[1:]:
            model.addCons(x[reqs[0]] == x[r2], name=f"grp_{gid}_{r2}")

# Passenger fraction constraints
total_pax = sum(int(requests[r]["passengers"]) for r in R_list)
min_pax = config["minimum_accepted_passenger_fraction"] * total_pax
model.addCons(quicksum(int(requests[r]["passengers"]) * x[r] for r in R_list) >= min_pax, name="min_pax_frac")

med_pax_total = sum(int(requests[r]["passengers"]) for r in R_list if requests[r]["priority_class"] == "medical")
min_med = config["minimum_medical_accepted_fraction"] * med_pax_total
model.addCons(quicksum(int(requests[r]["passengers"]) * x[r] for r in R_list if requests[r]["priority_class"] == "medical") >= min_med, name="min_med_frac")

ap_pax = sum(int(requests[r]["passengers"]) for r in R_list if requests[r]["market"] == "airport")
model.addCons(quicksum(int(requests[r]["passengers"]) * x[r] for r in R_list if requests[r]["market"] == "airport") >= config["minimum_airport_accepted_passengers"], name="min_airport_pax")

pri_reqs = [r for r in R_list if requests[r]["priority_class"] in ("airport", "medical")]
model.addCons(quicksum(1 - x[r] for r in pri_reqs) <= config["maximum_declined_priority_requests"], name="max_declined_pri")

for v, minp in floors.items():
    oreqs = [r for r in R_list if requests[r]["origin"] == v]
    if oreqs:
        model.addCons(quicksum(int(requests[r]["passengers"]) * x[r] for r in oreqs) >= minp, name=f"floor_{v}")

# Second-stage variables per scenario
# f[s,a,r,t]: aircraft a serves request r departing at slot t
# p[s,a,o,d,t]: reposition flight a from o to d departing at t
# c[s,a,v,t]: charge at v during slot t
# e[s,a,v,t]: energy charged
# soc[s,a,t]: SOC at end of slot t (boundary t+1)

f = {}
p = {}
c = {}
e = {}
soc = {}

obj_terms = []

for s in S_list:
    prob = float(scenarios[s]["probability"])
    ch_derate = float(scenarios[s]["charger_derate"])

    # SOC variables
    for a in A_list:
        for t in range(H):
            soc[(s, a, t)] = model.addVar(name=f"soc_{s}_{a}_{t}", vtype="C", lb=0.0, ub=float(aircraft[a]["battery_capacity_kwh"]), obj=0.0)

    # Flight variables for accepted requests
    for r in R_list:
        o = requests[r]["origin"]
        d = requests[r]["destination"]
        if not route_open(s, o, d):
            continue
        dur = route_dur(s, o, d)
        if dur is None:
            continue
        e_req = int(requests[r]["passengers"])
        for a in A_list:
            if int(aircraft[a]["seat_capacity"]) < e_req:
                continue
            rel = int(air_avail[(s, a)]["release_slot"])
            for t in range(int(requests[r]["earliest_slot"]), int(requests[r]["latest_depart_slot"]) + 1):
                if t < rel:
                    continue
                if t + dur > H:
                    continue
                f[(s, a, r, t)] = model.addVar(name=f"f_{s}_{a}_{r}_{t}", vtype="B", lb=0, ub=1, obj=0.0)

    # Reposition variables
    for a in A_list:
        for (o, d), rt in routes.items():
            if not route_open(s, o, d):
                continue
            dur = route_dur(s, o, d)
            if dur is None:
                continue
            rel = int(air_avail[(s, a)]["release_slot"])
            for t in range(rel, H):
                if t + dur > H:
                    continue
                p[(s, a, o, d, t)] = model.addVar(name=f"p_{s}_{a}_{o}_{d}_{t}", vtype="B", lb=0, ub=1, obj=0.0)

    # Charge variables
    for a in A_list:
        for v in V_list:
            for t in range(H):
                c[(s, a, v, t)] = model.addVar(name=f"c_{s}_{a}_{v}_{t}", vtype="B", lb=0, ub=1, obj=0.0)
                e[(s, a, v, t)] = model.addVar(name=f"e_{s}_{a}_{v}_{t}", vtype="C", lb=0.0, ub=float(aircraft[a]["battery_capacity_kwh"]), obj=0.0)

    # ---------- Constraints per scenario ----------

    # Service: each accepted request served exactly once
    for r in R_list:
        o = requests[r]["origin"]
        d = requests[r]["destination"]
        if not route_open(s, o, d):
            # Cannot serve in this scenario; must decline
            model.addCons(x[r] == 0, name=f"noserve_{s}_{r}")
            continue
        vars_r = [f[(s, a, r, t)] for (s2, a, r2, t) in f if s2 == s and r2 == r]
        if vars_r:
            model.addCons(quicksum(vars_r) == x[r], name=f"serve_{s}_{r}")
        else:
            model.addCons(x[r] == 0, name=f"noserve2_{s}_{r}")

    # Group spread
    for gid, g in groups.items():
        reqs = g["requests"]
        spread = g["spread"]
        # For each scenario, if group accepted, max dep - min dep <= spread
        # Use big-M: dep_r <= dep_r' + spread + M*(1-x_r) for all pairs
        # Simpler: for each pair, |dep_r - dep_r'| <= spread when both served
        # dep_r = sum_t t * f[s,a,r,t]
        # We'll add: for each pair (r1,r2), dep_r1 - dep_r2 <= spread + M*(2 - x_r1 - x_r2)
        # and dep_r2 - dep_r1 <= spread + M*(2 - x_r1 - x_r2)
        # M = H
        M = H
        for i in range(len(reqs)):
            for j in range(i+1, len(reqs)):
                r1, r2 = reqs[i], reqs[j]
                dep1 = quicksum(t * f[(s, a, r1, t)] for (s2, a, r2_, t) in f if s2 == s and r2_ == r1 for a in A_list)
                dep2 = quicksum(t * f[(s, a, r2, t)] for (s2, a, r2_, t) in f if s2 == s and r2_ == r2 for a in A_list)
                model.addCons(dep1 - dep2 <= spread + M * (2 - x[r1] - x[r2]), name=f"spread_{s}_{gid}_{r1}_{r2}_a")
                model.addCons(dep2 - dep1 <= spread + M * (2 - x[r1] - x[r2]), name=f"spread_{s}_{gid}_{r1}_{r2}_b")

    # Aircraft sequencing: location tracking
    # y[s,a,v,t] = 1 if aircraft a is at vertiport v at boundary after slot t (free to act at t+1)
    # We'll use a simpler approach: for each aircraft, track its location via flight/charge constraints

    # Energy and SOC
    for a in A_list:
        init_soc = float(aircraft[a]["initial_soc_kwh"]) * float(air_avail[(s, a)]["soc_derate"]) * float(scenarios[s]["soc_derate"])
        cap = float(aircraft[a]["battery_capacity_kwh"])
        high_soc = HIGH_SOC_FRAC * cap
        max_charge_per_slot = float(aircraft[a]["max_charge_kw"]) * ch_derate * SLOT_H

        # Initial SOC before slot 0
        # soc at end of slot t:
        # soc[s,a,t] = soc[s,a,t-1] + charge - flight_energy
        # For t=0: soc[s,a,0] = init_soc + charge[s,a,*,0] - flight_energy[s,a,*,0]

        for t in range(H):
            # SOC balance
            if t == 0:
                base_soc = init_soc
            else:
                base_soc = soc[(s, a, t-1)]

            # Charging at this slot
            charge_energy = quicksum(e[(s, a, v, t)] for v in V_list)

            # Flight energy consumed at this slot (flights departing at t)
            # A flight departing at t consumes energy immediately
            flight_energy = 0
            for (s2, a2, r, t2) in f:
                if s2 == s and a2 == a and t2 == t:
                    o = requests[r]["origin"]
                    d = requests[r]["destination"]
                    flight_energy += route_energy(s, o, d) * f[(s, a, r, t)]
            for (s2, a2, o, d, t2) in p:
                if s2 == s and a2 == a and t2 == t:
                    flight_energy += route_energy(s, o, d) * p[(s, a, o, d, t)]

            # SOC at end of slot t
            model.addCons(
                soc[(s, a, t)] == base_soc + charge_energy - flight_energy,
                name=f"soc_bal_{s}_{a}_{t}"
            )

            # Battery capacity
            model.addCons(soc[(s, a, t)] <= cap, name=f"soc_cap_{s}_{a}_{t}")

            # Reserve after flights: if a flight departs at t, SOC after must be >= reserve
            # Actually reserve is after every flight, so at end of flight
            # For flights departing at t with duration dur, the flight ends at t+dur-1
            # SOC at end of slot t+dur-1 must be >= reserve
            # We handle this by checking at each slot: if any flight ends at this slot, SOC >= reserve
            # Simpler: for each flight departing at t, SOC at t+dur-1 >= reserve
            # We'll add these constraints separately below

        # Reserve constraints for flights
        for (s2, a2, r, t) in list(f.keys()):
            if s2 != s or a2 != a:
                continue
            o = requests[r]["origin"]
            d = requests[r]["destination"]
            dur = route_dur(s, o, d)
            end_t = t + dur - 1
            if end_t < H:
                model.addCons(
                    soc[(s, a, end_t)] >= RESERVE_SOC,
                    name=f"reserve_{s}_{a}_{r}_{t}"
                )

        for (s2, a2, o, d, t) in list(p.keys()):
            if s2 != s or a2 != a:
                continue
            dur = route_dur(s, o, d)
            end_t = t + dur - 1
            if end_t < H:
                model.addCons(
                    soc[(s, a, end_t)] >= RESERVE_SOC,
                    name=f"reserve_p_{s}_{a}_{o}_{d}_{t}"
                )

        # Charge limits
        for v in V_list:
            for t in range(H):
                # Power limit
                model.addCons(e[(s, a, v, t)] <= max_charge_per_slot * c[(s, a, v, t)], name=f"chg_pow_{s}_{a}_{v}_{t}")
                # Taper: if SOC after charge > high_soc, excess <= taper_frac * max_charge_per_slot
                # SOC after charge at (v,t) = soc[s,a,t] (if only charging)
                # This is complex; approximate: e[s,a,v,t] <= max_charge_per_slot
                # and if soc[s,a,t] > high_soc, then e[s,a,v,t] - (cap - soc_before) <= taper... 
                # Simplified: total charge in slot <= max_charge_per_slot, and if ending above high_soc,
                # the amount above (high_soc - soc_before) <= taper_frac * max_charge_per_slot
                # We'll skip the taper for now to keep model tractable, but add a simple bound
                pass

    # Pad capacity per slot per vertiport
    for v in V_list:
        pad_cap = int(vertiports[v]["pad_count"])
        for t in range(H):
            # Departures from v at t
            dep_count = 0
            for (s2, a, r, t2) in f:
                if s2 == s and t2 == t and requests[r]["origin"] == v:
                    dep_count += f[(s, a, r, t)]
            for (s2, a, o, d, t2) in p:
                if s2 == s and t2 == t and o == v:
                    dep_count += p[(s, a, o, d, t)]

            # Arrivals at v at t: flights with end_slot = t
            arr_count = 0
            for (s2, a, r, t2) in f:
                if s2 == s and requests[r]["destination"] == v:
                    dur = route_dur(s, requests[r]["origin"], v)
                    if dur is not None and t2 + dur - 1 == t:
                        arr_count += f[(s, a, r, t2)]
            for (s2, a, o, d, t2) in p:
                if s2 == s and d == v:
                    dur = route_dur(s, o, v)
                    if dur is not None and t2 + dur - 1 == t:
                        arr_count += p[(s, a, o, d, t2)]

            model.addCons(dep_count + arr_count <= pad_cap, name=f"pad_{s}_{v}_{t}")

    # Charger capacity
    for v in V_list:
        chg_cap = int(vertiports[v]["charger_count"])
        for t in range(H):
            model.addCons(quicksum(c[(s, a, v, t)] for a in A_list) <= chg_cap, name=f"chg_cap_{s}_{v}_{t}")

    # Grid headroom
    for v in V_list:
        grid_lim = float(vertiports[v]["grid_kw_limit"])
        for t in range(H):
            g = grid.get((v, t))
            mult = float(g["grid_limit_multiplier"]) if g else 1.0
            lim = grid_lim * mult * ch_derate
            # Power = energy / slot_hours
            total_power = quicksum(e[(s, a, v, t)] / SLOT_H for a in A_list)
            model.addCons(total_power <= lim, name=f"grid_{s}_{v}_{t}")

    # Corridor capacity
    corridors = set(rt["corridor_id"] for rt in routes.values())
    for cor in corridors:
        for t in range(H):
            # Count flights occupying corridor in slot t
            cor_count = 0
            for (s2, a, r, t2) in f:
                if s2 == s:
                    o = requests[r]["origin"]
                    d = requests[r]["destination"]
                    rt = routes.get((o, d))
                    if rt and rt["corridor_id"] == cor:
                        dur = route_dur(s, o, d)
                        if dur is not None and t2 <= t < t2 + dur:
                            cor_count += f[(s, a, r, t2)]
            for (s2, a, o, d, t2) in p:
                if s2 == s:
                    rt = routes.get((o, d))
                    if rt and rt["corridor_id"] == cor:
                        dur = route_dur(s, o, d)
                        if dur is not None and t2 <= t < t2 + dur:
                            cor_count += p[(s, a, o, d, t2)]

            # Base capacity
            base_cap = max(int(routes[(o,d)]["corridor_capacity_per_slot"]) for (o,d),rt in routes.items() if rt["corridor_id"]==cor)
            # Check corridor controls
            ctrl_val = None
            for (s2, c2, st, en), mv in corridor_ctrl.items():
                if s2 == s and c2 == cor and st <= t <= en:
                    ctrl_val = mv
                    break
            cap = min(base_cap, ctrl_val) if ctrl_val is not None else base_cap
            model.addCons(cor_count <= cap, name=f"cor_{s}_{cor}_{t}")

    # Noise quota
    for v in V_list:
        for t in range(H):
            period = time_slots[t]["period"]
            quota = float(vertiports[v]["departure_noise_quota_day"] if period == "day" else vertiports[v]["departure_noise_quota_evening"])
            noise = 0
            for (s2, a, r, t2) in f:
                if s2 == s and t2 == t and requests[r]["origin"] == v:
                    o = requests[r]["origin"]
                    d = requests[r]["destination"]
                    rt = routes.get((o, d))
                    if rt:
                        noise += float(rt["noise_points"]) * float(aircraft[a]["noise_class"]) * f[(s, a, r, t)]
            for (s2, a, o, d, t2) in p:
                if s2 == s and t2 == t and o == v:
                    rt = routes.get((o, d))
                    if rt:
                        noise += float(rt["noise_points"]) * float(aircraft[a]["noise_class"]) * p[(s, a, o, d, t)]
            model.addCons(noise <= quota, name=f"noise_{s}_{v}_{t}")

    # Service windows
    for w in svc_windows:
        if w["scenario_id"] != s:
            continue
        a = w["aircraft_id"]
        v = w["vertiport_id"]
        st = int(w["start_slot"])
        en = int(w["end_slot"])
        min_soc = float(w["min_soc_kwh"])
        # Aircraft must be at v and idle (no flights) during [st, en-1]
        # No flights departing or arriving during this window
        for t in range(st, en):
            # No flights departing from any vertiport
            for (s2, a2, r, t2) in f:
                if s2 == s and a2 == a and t2 == t:
                    model.addCons(f[(s, a, r, t)] == 0, name=f"sw_no_dep_{s}_{a}_{r}_{t}")
            for (s2, a2, o, d, t2) in p:
                if s2 == s and a2 == a and t2 == t:
                    model.addCons(p[(s, a, o, d, t)] == 0, name=f"sw_no_repos_{s}_{a}_{o}_{d}_{t}")
            # No flights arriving
            for (s2, a2, r, t2) in f:
                if s2 == s and a2 == a:
                    o = requests[r]["origin"]
                    d = requests[r]["destination"]
                    dur = route_dur(s, o, d)
                    if dur is not None and t2 + dur - 1 == t:
                        model.addCons(f[(s, a, r, t2)] == 0, name=f"sw_no_arr_{s}_{a}_{r}_{t2}")
            for (s2, a2, o, d, t2) in p:
                if s2 == s and a2 == a:
                    dur = route_dur(s, o, d)
                    if dur is not None and t2 + dur - 1 == t:
                        model.addCons(p[(s, a, o, d, t2)] == 0, name=f"sw_no_arr_p_{s}_{a}_{o}_{d}_{t2}")
            # SOC >= min_soc
            model.addCons(soc[(s, a, t)] >= min_soc, name=f"sw_soc_{s}_{a}_{t}")

    # Emergency reserves
    for res in reserves:
        if res["scenario_id"] != s:
            continue
        v = res["vertiport_id"]
        t = int(res["slot"])
        min_idle = int(res["min_idle_aircraft"])
        min_soc = float(res["min_soc_kwh"])
        # At boundary t, at least min_idle aircraft at v with soc >= min_soc and not flying
        # Approximate: count aircraft with soc >= min_soc at v (we don't track location explicitly)
        # This is a simplification; in a full model we'd track location
        # For now, count aircraft with sufficient SOC
        idle_count = 0
        for a in A_list:
            # Create indicator: aircraft a counts if soc >= min_soc
            # Use big-M: soc[s,a,t] >= min_soc - M*(1-indicator)
            # Simplified: just count all aircraft with soc >= min_soc (relaxation)
            pass
        # Skip for now - this is a relaxation

    # Objective terms for this scenario
    # Revenue
    revenue = 0
    for r in R_list:
        revenue += float(requests[r]["fare_per_passenger"]) * int(requests[r]["passengers"]) * x[r]

    # Decline penalty
    decline_pen = 0
    for r in R_list:
        decline_pen += float(requests[r]["decline_penalty"]) * (1 - x[r])

    # Operating cost
    op_cost = 0
    for (s2, a, r, t) in f:
        if s2 == s:
            o = requests[r]["origin"]
            d = requests[r]["destination"]
            op_cost += float(routes[(o, d)]["operating_cost"]) * f[(s, a, r, t)]

    # Reposition cost
    repos_cost = 0
    for (s2, a, o, d, t) in p:
        if s2 == s:
            repos_cost += REPOS_COST * route_energy(s, o, d) * p[(s, a, o, d, t)]

    # Charging cost
    chg_cost = 0
    for (s2, a, v, t) in e:
        if s2 == s:
            g = grid.get((v, t))
            price = float(g["price_per_kwh"]) if g else 0.2
            chg_cost += price * e[(s, a, v, t)]

    # Delay penalty
    delay_pen = 0
    for r in R_list:
        earliest = int(requests[r]["earliest_slot"])
        pax = int(requests[r]["passengers"])
        dep = quicksum(t * f[(s, a, r, t)] for (s2, a, r2, t) in f if s2 == s and r2 == r for a in A_list)
        delay_pen += DELAY_PEN * pax * (dep - earliest) * x[r]

    scenario_profit = revenue - decline_pen - op_cost - repos_cost - chg_cost - delay_pen
    obj_terms.append(prob * scenario_profit)

# Set objective
model.setObjective(quicksum(obj_terms), sense="maximize")

# ---------- Solve ----------
try:
    model.optimize()
    status = model.getStatus()
    print(f"Solver status: {status}")
    print(f"Objective: {model.getObjVal():.4f}")
    print(f"Num solutions: {model.getNSols()}")
except Exception as ex:
    print(f"Solver error: {ex}")
    status = "error"

# ---------- Extract solution ----------
solution_rows = []

# Accept/decline rows
for r in R_list:
    val = model.getVal(x[r]) if status not in ("error",) else 0.0
    dec = "accept" if val > 0.5 else "decline"
    solution_rows.append(["accept", "", "", r, "", "", "", "", "", "", dec])

# Flight, reposition, charge rows
for s in S_list:
    for (s2, a, r, t) in f:
        if s2 != s:
            continue
        val = model.getVal(f[(s, a, r, t)])
        if val > 0.5:
            o = requests[r]["origin"]
            d = requests[r]["destination"]
            dur = route_dur(s, o, d)
            end_t = t + dur - 1
            energy = route_energy(s, o, d)
            qty = int(requests[r]["passengers"])
            solution_rows.append(["flight", s, a, r, o, d, str(t), str(end_t), f"{energy:.8f}", str(qty), "serve"])

    for (s2, a, o, d, t) in p:
        if s2 != s:
            continue
        val = model.getVal(p[(s, a, o, d, t)])
        if val > 0.5:
            dur = route_dur(s, o, d)
            end_t = t + dur - 1
            energy = route_energy(s, o, d)
            solution_rows.append(["reposition", s, a, "", o, d, str(t), str(end_t), f"{energy:.8f}", "", "reposition"])

    for (s2, a, v, t) in e:
        if s2 != s:
            continue
        val = model.getVal(e[(s, a, v, t)])
        if val > 1e-6:
            solution_rows.append(["charge", s, a, "", v, "", str(t), str(t+1), f"{val:.8f}", "", "charge"])

# Write solution
os.makedirs("/app/submissions", exist_ok=True)
with open(OUT, "w", newline="") as fh:
    w = csv.writer(fh)
    w.writerow(["row_type","scenario_id","aircraft_id","request_id","origin","destination","start_slot","end_slot","energy_kwh","quantity","decision"])
    for row in solution_rows:
        w.writerow(row)

print(f"Wrote {len(solution_rows)} rows to {OUT}")

# Free model
try:
    model.free()
except:
    pass
